3//!
4//! This module is designed to parallelize operations on a dependency graph
5//! where some tasks must be delayed until all dependencies are met, such as in
6//! the following case:
7//!
8//! # Example
9//!
10//! ```
11//! # use topograph::{prelude::*, executor, graph};
12//! # use std::sync::{Arc, atomic::{AtomicU32, Ordering}};
13//! enum Job {
14//!     Foo,
15//!     Bar,
16//!     Baz,
17//!     Assert,
18//! }
19//!
20//! let data = Arc::new(AtomicU32::new(0));
21//! # let data_1 = data.clone();
22//!
23//! let pool = executor::Builder::new(executor::Blocking).build_graph(move |job, handle| {
24//!     match job {
25//!         Job::Foo => {
26//!             let mut deps = handle.create_node(Job::Assert, 2);
27//!
28//!             handle.push_dependency(Job::Bar, Some(deps.get_in_edge()));
29//!             handle.push_dependency(Job::Baz, Some(deps.get_in_edge()));
30//!         },
31//!         Job::Bar => {
32//!             data.fetch_add(1, Ordering::SeqCst);
33//!         },
34//!         Job::Baz => {
35//!             data.fetch_add(2, Ordering::SeqCst);
36//!         },
37//!         Job::Assert => {
38//!             assert_eq!(data.swap(1337, Ordering::SeqCst), 3);
39//!         },
40//!     }
41//!
42//!     Ok(())
43//! }).unwrap();
44//!
45//! pool.push(Job::Foo);
46//! pool.join();
47//! # let data = data_1;
48//!
49//! assert_eq!(data.load(Ordering::SeqCst), 1337);
50//! ```
51//!
52//! The above code does not panic because the scheduler ensures `Assert` is not
53//! processed until `Bar` and `Baz` complete.
54//!
55//! Additionally, since dependent tasks should only run if all dependencies
56//! succeed, this module alters the worker task type passed to the underlying
57//! executor to allow returning a simple `Result` value.
